using System.Windows; using Forms=System.Windows.Forms;
namespace ChichiCapture;public partial class SettingsWindow:Window{readonly AppSettings s;public SettingsWindow(AppSettings settings){InitializeComponent();s=settings;Auto.IsChecked=s.AutoSave;Folder.Text=s.SaveFolder;Ctrl.IsChecked=s.Ctrl;Shift.IsChecked=s.Shift;Alt.IsChecked=s.Alt;foreach(char c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ")KeyBox.Items.Add(c.ToString());KeyBox.SelectedItem=((char)s.HotKey).ToString();}void Browse_Click(object sender,RoutedEventArgs e){using var d=new FolderBrowserDialog{SelectedPath=Folder.Text};if(d.ShowDialog()==Forms.DialogResult.OK)Folder.Text=d.SelectedPath;}void Save_Click(object sender,RoutedEventArgs e){if(Ctrl.IsChecked!=true&&Shift.IsChecked!=true&&Alt.IsChecked!=true){MessageBox.Show("Ctrl, Shift, Alt 중 하나 이상을 선택하세요.");return;}s.AutoSave=Auto.IsChecked==true;s.SaveFolder=Folder.Text;s.Ctrl=Ctrl.IsChecked==true;s.Shift=Shift.IsChecked==true;s.Alt=Alt.IsChecked==true;s.HotKey=(int)((string)KeyBox.SelectedItem)[0];DialogResult=true;}}
